function writeUInt16BE(bytes, index, value) {
    bytes[index] = (value >> 8) & 0xff;
    bytes[index + 1] = value & 0xff;
}

function writeInt16BE(bytes, index, value) {
    const normalized = value < 0 ? 0x10000 + value : value;
    writeUInt16BE(bytes, index, normalized);
}

const steps = [
    { temp: 22.4, adc: 512, no2: 620, ethanol: 880, voc: 1450, co: 910 },
    { temp: 23.1, adc: 505, no2: 750, ethanol: 1100, voc: 1900, co: 1040 },
    { temp: 24.0, adc: 498, no2: 1020, ethanol: 1500, voc: 2400, co: 1320 },
    { temp: 25.2, adc: 490, no2: 1800, ethanol: 2600, voc: 4200, co: 2100 }
];

let cursor = context.get('cursor') || 0;
const sample = steps[cursor % steps.length];
cursor += 1;
context.set('cursor', cursor);

const desired = flow.get('desiredLedControl') || { mode: 0, blinkPeriodDs: 10 };
let ledOutput = desired.mode === 2 ? ((cursor % 2) ? 1 : 0) : (desired.mode === 1 ? 1 : 0);
const bytes = new Array(17).fill(0);
writeInt16BE(bytes, 0, Math.round(sample.temp * 100));
writeUInt16BE(bytes, 2, sample.adc);
writeUInt16BE(bytes, 4, sample.no2);
writeUInt16BE(bytes, 6, sample.ethanol);
writeUInt16BE(bytes, 8, sample.voc);
writeUInt16BE(bytes, 10, sample.co);
bytes[12] = cursor % 256;
bytes[13] = 0x0f;
bytes[14] = desired.mode;
bytes[15] = desired.blinkPeriodDs;
bytes[16] = ledOutput;

msg.topic = 'v3/demo-app@ttn/devices/demo-lorae5/up';
msg.payload = {
    end_device_ids: {
        device_id: 'demo-lorae5',
        application_ids: { application_id: 'demo-app' },
        dev_eui: '0004A30B001C0530'
    },
    received_at: new Date().toISOString(),
    uplink_message: {
        f_port: 15,
        f_cnt: bytes[12],
        frm_payload: Buffer.from(bytes).toString('base64'),
        decoded_payload: {
            temperature: sample.temp,
            temperature_adc: sample.adc,
            gas_no2_raw: sample.no2,
            gas_ethanol_raw: sample.ethanol,
            gas_voc_raw: sample.voc,
            gas_co_raw: sample.co,
            counter: bytes[12],
            flags: bytes[13],
            temp_ok: true,
            gas_ok: true,
            gas_warmup_done: true,
            real_sensors: true,
            led_mode_code: desired.mode,
            led_mode: desired.mode === 2 ? 'blink' : (desired.mode === 1 ? 'on' : 'off'),
            blink_period_ms: desired.blinkPeriodDs * 100,
            led: ledOutput === 1
        },
        consumed_airtime: '0.071936s',
        settings: {
            frequency: '868100000',
            data_rate: {
                lora: {
                    bandwidth: 125000,
                    spreading_factor: 7,
                    coding_rate: '4/5'
                }
            }
        },
        rx_metadata: [
            { gateway_ids: { gateway_id: 'demo-gw-1' }, rssi: -88, snr: 8.5 },
            { gateway_ids: { gateway_id: 'demo-gw-2' }, rssi: -94, snr: 6.1 }
        ]
    }
};
return msg;

const event = msg.payload || {};
const firstDownlink = Array.isArray(event.downlinks) && event.downlinks.length ? event.downlinks[0] : (event.downlink_queued || null);
const frmPayload = firstDownlink && firstDownlink.frm_payload ? firstDownlink.frm_payload : 'n/a';
const deviceId = (event.end_device_ids && event.end_device_ids.device_id) || flow.get('lastDeviceId') || 'device-inconnu';
const count = (flow.get('downlinkQueuedCount') || 0) + 1;
flow.set('downlinkQueuedCount', count);
return [
    { payload: 'TTS a accepte un downlink pour ' + deviceId + ' (frm_payload=' + frmPayload + ').' },
    { payload: String(count) }
];

function base64ToBytes(value) {
    if (!value) return [];
    return Array.from(Buffer.from(value, 'base64'));
}

function readUInt16BE(bytes, index) {
    if (bytes.length < index + 2) return null;
    return ((bytes[index] || 0) << 8) | (bytes[index + 1] || 0);
}

function readInt16BE(bytes, index) {
    const value = readUInt16BE(bytes, index);
    if (value === null) return null;
    return value > 0x7fff ? value - 0x10000 : value;
}

function toNumber(value, fallback) {
    const num = Number(value);
    return Number.isFinite(num) ? num : fallback;
}

function asBool(value, fallback) {
    if (value === true || value === false) return value;
    if (value === 1 || value === 0) return value === 1;
    return fallback;
}

function normalizeMode(value, fallback) {
    if (value === 'blink') return 2;
    if (value === 'on' || value === true) return 1;
    if (value === 'off' || value === false) return 0;
    const num = Number(value);
    if (Number.isFinite(num) && num >= 0 && num <= 2) return num;
    return fallback;
}

function normalizeBlinkPeriodDs(value, fallback) {
    const num = Number(value);
    if (!Number.isFinite(num)) return fallback;
    return Math.min(100, Math.max(2, Math.round(num / 100)));
}

function buildModeLabel(mode) {
    if (mode === 2) return 'blink';
    if (mode === 1) return 'on';
    return 'off';
}

function buildDesiredText(control) {
    if (control.mode === 2) {
        return 'Consigne memorisee: BLINK ' + (control.blinkPeriodDs * 100) + ' ms';
    }
    return 'Consigne memorisee: LED ' + (control.mode === 1 ? 'allumee' : 'eteinte');
}

function buildDownlinkMessage(topic, control) {
    return {
        topic,
        payload: {
            downlinks: [
                {
                    f_port: 15,
                    frm_payload: Buffer.from([control.mode, control.blinkPeriodDs]).toString('base64'),
                    priority: 'NORMAL'
                }
            ]
        }
    };
}

function qualityLabel(index, gasOk, gasWarmupDone) {
    if (!gasOk) return 'capteur gaz indisponible';
    if (!gasWarmupDone) return 'prechauffage en cours';
    if (index < 1500) return 'faible';
    if (index < 5000) return 'modere';
    if (index < 15000) return 'eleve';
    return 'critique';
}

function formatGas(name, value) {
    return value === null ? (name + '=n/a') : (name + '=' + value);
}

const packet = msg.payload || {};
const uplink = packet.uplink_message || packet;
const decoded = uplink.decoded_payload || {};
const bytes = Array.isArray(uplink.bytes) ? uplink.bytes : base64ToBytes(uplink.frm_payload);
const deviceId = (packet.end_device_ids && packet.end_device_ids.device_id) || packet.device_id || 'device-inconnu';
const receivedAt = packet.received_at || new Date().toISOString();
const receivedLabel = new Date(receivedAt).toLocaleString('fr-FR', { hour12: false });
const downlinkTopic = msg.topic && msg.topic.endsWith('/up') ? msg.topic.replace(/\/up$/, '/down/replace') : '';
if (downlinkTopic) {
    flow.set('lastDownlinkTopic', downlinkTopic);
    flow.set('lastDeviceId', deviceId);
}

const temperature = toNumber(decoded.temperature, bytes.length >= 2 ? readInt16BE(bytes, 0) / 100 : null);
const temperatureAdc = toNumber(decoded.temperature_adc, bytes.length >= 4 ? readUInt16BE(bytes, 2) : null);
const gasNo2 = toNumber(decoded.gas_no2_raw !== undefined ? decoded.gas_no2_raw : decoded.gas_no2, bytes.length >= 6 ? readUInt16BE(bytes, 4) : null);
const gasEthanol = toNumber(decoded.gas_ethanol_raw !== undefined ? decoded.gas_ethanol_raw : decoded.gas_ethanol, bytes.length >= 8 ? readUInt16BE(bytes, 6) : null);
const gasVoc = toNumber(decoded.gas_voc_raw !== undefined ? decoded.gas_voc_raw : decoded.gas_voc, bytes.length >= 10 ? readUInt16BE(bytes, 8) : null);
const gasCo = toNumber(decoded.gas_co_raw !== undefined ? decoded.gas_co_raw : decoded.gas_co, bytes.length >= 12 ? readUInt16BE(bytes, 10) : null);
const counter = toNumber(decoded.counter, bytes.length >= 13 ? bytes[12] : toNumber(uplink.f_cnt, null));
const flags = toNumber(decoded.flags, bytes.length >= 14 ? bytes[13] : 0) || 0;
const tempOk = asBool(decoded.temp_ok, (flags & 0x01) === 0x01);
const gasOk = asBool(decoded.gas_ok, (flags & 0x02) === 0x02);
const gasWarmupDone = asBool(decoded.gas_warmup_done, (flags & 0x04) === 0x04);
const ledState = asBool(decoded.led, bytes.length >= 17 ? bytes[16] === 1 : false) ? 1 : 0;
const actualMode = normalizeMode(decoded.led_mode_code !== undefined ? decoded.led_mode_code : decoded.led_mode, bytes.length >= 15 ? bytes[14] : ledState);
const actualBlinkPeriodDs = normalizeBlinkPeriodDs(decoded.blink_period_ms !== undefined ? decoded.blink_period_ms : (bytes.length >= 16 ? bytes[15] * 100 : undefined), 10);
const actualModeLabel = buildModeLabel(actualMode);
const airIndex = Math.max(gasNo2 || 0, gasEthanol || 0, gasVoc || 0, gasCo || 0);
const airQuality = qualityLabel(airIndex, gasOk, gasWarmupDone);

let desiredControl = flow.get('desiredLedControl');
if (!desiredControl || typeof desiredControl !== 'object') {
    desiredControl = { mode: actualMode, blinkPeriodDs: actualBlinkPeriodDs };
    flow.set('desiredLedControl', desiredControl);
}

const desiredText = buildDesiredText(desiredControl);
const actualLedText = actualMode === 2
    ? ('LED clignote | ' + (actualBlinkPeriodDs * 100) + ' ms')
    : ('LED ' + (ledState ? 'allumee' : 'eteinte'));
const targetText = downlinkTopic || flow.get('lastDownlinkTopic') || 'En attente d un uplink reel pour connaitre la cible du downlink';

const alerts = [];
if (!tempOk) alerts.push('temperature indisponible');
if (!gasOk) alerts.push('capteur gaz indisponible');
if (gasOk && !gasWarmupDone) alerts.push('capteur gaz en prechauffage');
if (temperature !== null && temperature >= 35) alerts.push('temperature elevee');
if (temperature !== null && temperature <= 5) alerts.push('temperature basse');
if (gasOk && gasWarmupDone && airIndex >= 15000) alerts.push('niveau gaz brut critique');
else if (gasOk && gasWarmupDone && airIndex >= 5000) alerts.push('niveau gaz brut eleve');
if (desiredControl.mode !== actualMode || (desiredControl.mode === 2 && desiredControl.blinkPeriodDs !== actualBlinkPeriodDs)) {
    alerts.push('etat LED non conforme a la consigne');
}

const rxMetadata = Array.isArray(uplink.rx_metadata) ? uplink.rx_metadata : [];
const rssiValues = rxMetadata.map((item) => toNumber(item.rssi, null)).filter((value) => value !== null);
const snrValues = rxMetadata.map((item) => toNumber(item.snr, null)).filter((value) => value !== null);
const bestRssi = rssiValues.length ? Math.max.apply(null, rssiValues) : null;
const bestSnr = snrValues.length ? Math.max.apply(null, snrValues) : null;
const gatewayCount = rxMetadata.length;
const loraRate = uplink.settings && uplink.settings.data_rate && uplink.settings.data_rate.lora ? uplink.settings.data_rate.lora : {};
const dataRate = loraRate.spreading_factor ? ('SF' + loraRate.spreading_factor + ' / BW ' + Math.round((loraRate.bandwidth || 0) / 1000) + ' kHz') : 'n/a';
const airTime = uplink.consumed_airtime || uplink.airtime || 'n/a';

const uplinkCount = (flow.get('uplinkCount') || 0) + 1;
flow.set('uplinkCount', uplinkCount);
const downlinkQueuedCount = flow.get('downlinkQueuedCount') || 0;
const manualCommandCount = flow.get('manualCommandCount') || 0;
let autoRetryCount = flow.get('autoRetryCount') || 0;

let autoRetryMessage = null;
let autoRetryStatus = null;
if (targetText && !targetText.startsWith('En attente') && (desiredControl.mode !== actualMode || (desiredControl.mode === 2 && desiredControl.blinkPeriodDs !== actualBlinkPeriodDs))) {
    autoRetryCount += 1;
    flow.set('autoRetryCount', autoRetryCount);
    autoRetryMessage = buildDownlinkMessage(targetText, desiredControl);
    autoRetryStatus = {
        payload: 'Re-emission automatique de la consigne LED car le noeud remonte encore ' + actualModeLabel + ' / ' + (actualBlinkPeriodDs * 100) + ' ms.'
    };
}

const summary = [
    temperature !== null ? ('temperature=' + temperature.toFixed(2) + ' degC') : 'temperature=n/a',
    temperatureAdc !== null ? ('adc=' + temperatureAdc) : 'adc=n/a',
    formatGas('NO2', gasNo2),
    formatGas('C2H5OH', gasEthanol),
    formatGas('VOC', gasVoc),
    formatGas('CO', gasCo),
    'air_index=' + airIndex,
    'qualite=' + airQuality
].join(' | ');

const flagsText = [
    'temp_ok=' + tempOk,
    'gas_ok=' + gasOk,
    'gas_warmup_done=' + gasWarmupDone,
    'real_sensors=' + (((flags & 0x08) === 0x08) ? 'true' : 'false'),
    'led=' + (ledState === 1),
    'led_mode=' + actualModeLabel,
    'blink_period_ms=' + (actualBlinkPeriodDs * 100)
].join(' | ');

const heroPayload = {
    device: deviceId,
    received: receivedLabel,
    temperature: temperature !== null ? temperature.toFixed(2) : '--',
    temperatureAdc: temperatureAdc !== null ? String(temperatureAdc) : 'n/a',
    airQuality,
    warmup: gasWarmupDone ? 'termine' : 'en cours',
    no2: gasNo2 !== null ? String(gasNo2) : 'n/a',
    ethanol: gasEthanol !== null ? String(gasEthanol) : 'n/a',
    voc: gasVoc !== null ? String(gasVoc) : 'n/a',
    co: gasCo !== null ? String(gasCo) : 'n/a',
    ledText: actualLedText,
    rssi: bestRssi !== null ? (bestRssi + ' dBm') : 'n/a',
    snr: bestSnr !== null ? (bestSnr.toFixed(1) + ' dB') : 'n/a',
    alerts: alerts.length ? alerts.join(' | ') : 'RAS'
};

const kpiPayload = {
    temperature: temperature !== null ? temperature.toFixed(2) : '--',
    no2: gasNo2 !== null ? String(gasNo2) : '--',
    ethanol: gasEthanol !== null ? String(gasEthanol) : '--',
    voc: gasVoc !== null ? String(gasVoc) : '--',
    co: gasCo !== null ? String(gasCo) : '--',
    airIndex: String(airIndex),
    ledMode: actualMode === 2 ? ('BLINK ' + (actualBlinkPeriodDs * 100) + ' ms') : (actualMode === 1 ? 'ON' : 'OFF'),
    warmup: gasWarmupDone ? 'pret' : 'prechauffage'
};

const outputs = [
    { payload: deviceId },
    { payload: receivedLabel },
    { payload: airQuality },
    { payload: alerts.length ? alerts.join(' | ') : 'RAS' },
    { payload: summary },
    { payload: tempOk ? 'Temperature OK' : 'Temperature indisponible' },
    { payload: gasOk ? ('Capteur gaz ' + (gasWarmupDone ? 'pret' : 'en prechauffage')) : 'Capteur gaz indisponible' },
    { payload: actualLedText },
    { payload: targetText },
    { payload: heroPayload },
    { payload: kpiPayload },
    temperature !== null ? { payload: Number(temperature.toFixed(2)) } : null,
    gasNo2 !== null ? { payload: gasNo2 } : null,
    gasEthanol !== null ? { payload: gasEthanol } : null,
    gasVoc !== null ? { payload: gasVoc } : null,
    gasCo !== null ? { payload: gasCo } : null,
    { payload: airIndex },
    { payload: temperatureAdc !== null ? String(temperatureAdc) : 'n/a' },
    { payload: counter !== null ? String(counter) : 'n/a' },
    { payload: gasWarmupDone ? 'Capteur gaz prechauffe' : 'Capteur gaz en prechauffage (jusqu a 10 min selon la doc Seeed)' },
    temperature !== null ? { payload: Number(temperature.toFixed(2)), topic: 'Temperature' } : null,
    gasNo2 !== null ? { payload: gasNo2, topic: 'NO2' } : null,
    gasEthanol !== null ? { payload: gasEthanol, topic: 'Ethanol' } : null,
    gasVoc !== null ? { payload: gasVoc, topic: 'VOC' } : null,
    gasCo !== null ? { payload: gasCo, topic: 'CO' } : null,
    { payload: airIndex, topic: 'AirIndex' },
    { payload: bestRssi !== null ? (bestRssi + ' dBm') : 'n/a' },
    { payload: bestSnr !== null ? (bestSnr.toFixed(1) + ' dB') : 'n/a' },
    { payload: String(gatewayCount) },
    { payload: dataRate },
    { payload: String(airTime) },
    { payload: String(uplinkCount) },
    { payload: String(autoRetryCount) },
    { payload: String(downlinkQueuedCount) },
    { payload: String(manualCommandCount) },
    { payload: msg.topic || 'n/a' },
    { payload: bytes.length ? bytes.join(', ') : (uplink.frm_payload || 'n/a') },
    { payload: flagsText },
    { payload: JSON.stringify(packet, null, 2) },
    autoRetryMessage,
    autoRetryStatus
];

return outputs;

function normalizeMode(value, fallback) {
    const num = Number(value);
    if (Number.isFinite(num) && num >= 0 && num <= 2) return num;
    return fallback;
}

function normalizeBlinkPeriodDs(value, fallback) {
    const num = Number(value);
    if (!Number.isFinite(num)) return fallback;
    return Math.min(100, Math.max(2, Math.round(num / 100)));
}

function buildDesiredText(control) {
    if (control.mode === 2) {
        return 'Consigne memorisee: BLINK ' + (control.blinkPeriodDs * 100) + ' ms';
    }
    return 'Consigne memorisee: LED ' + (control.mode === 1 ? 'allumee' : 'eteinte');
}

function buildDownlinkMessage(topic, control) {
    return {
        topic,
        payload: {
            downlinks: [
                {
                    f_port: 15,
                    frm_payload: Buffer.from([control.mode, control.blinkPeriodDs]).toString('base64'),
                    priority: 'NORMAL'
                }
            ]
        }
    };
}

let desiredControl = flow.get('desiredLedControl');
if (!desiredControl || typeof desiredControl !== 'object') {
    desiredControl = { mode: 0, blinkPeriodDs: 10 };
}

const input = msg.payload || {};
const downlinkTopic = flow.get('lastDownlinkTopic');
const deviceId = flow.get('lastDeviceId') || 'device-inconnu';
let manualCommandCount = flow.get('manualCommandCount') || 0;
let statusText = 'Consigne LED mise a jour.';
let shouldSend = false;

if (input.mode !== undefined) {
    desiredControl.mode = normalizeMode(input.mode, desiredControl.mode);
    manualCommandCount += 1;
    shouldSend = true;
    statusText = desiredControl.mode === 2 ? 'Mode BLINK active.' : (desiredControl.mode === 1 ? 'Mode ON actif.' : 'Mode OFF actif.');
}

if (input.blink_period_ms !== undefined) {
    desiredControl.blinkPeriodDs = normalizeBlinkPeriodDs(input.blink_period_ms, desiredControl.blinkPeriodDs);
    manualCommandCount += 1;
    if (desiredControl.mode === 2) {
        shouldSend = true;
        statusText = 'Periode de blink mise a ' + (desiredControl.blinkPeriodDs * 100) + ' ms.';
    } else {
        statusText = 'Periode de blink memorisee a ' + (desiredControl.blinkPeriodDs * 100) + ' ms.';
    }
}

flow.set('desiredLedControl', desiredControl);
flow.set('manualCommandCount', manualCommandCount);
const desiredText = buildDesiredText(desiredControl);

if (!downlinkTopic) {
    return [
        null,
        { payload: 'Aucun uplink recu: cible downlink inconnue. La consigne reste memorisee.' },
        { payload: desiredText },
        { payload: String(manualCommandCount) }
    ];
}

if (!shouldSend) {
    return [
        null,
        { payload: statusText },
        { payload: desiredText },
        { payload: String(manualCommandCount) }
    ];
}

return [
    buildDownlinkMessage(downlinkTopic, desiredControl),
    { payload: statusText + ' Envoi via downlink/replace pour ' + deviceId + '.' },
    { payload: desiredText },
    { payload: String(manualCommandCount) }
];

const d = msg.payload;
const deviceId = d.device || 'unknown';

let devices = flow.get('api_devices') || {};
devices[deviceId] = {
    deviceId: deviceId,
    timestamp: new Date().toISOString(),
    temperature: parseFloat(d.temperature) || 0,
    temperatureAdc: d.temperatureAdc,
    no2: parseInt(d.no2) || 0,
    ethanol: parseInt(d.ethanol) || 0,
    voc: parseInt(d.voc) || 0,
    co: parseInt(d.co) || 0,
    airQuality: d.airQuality,
    warmup: d.warmup,
    ledText: d.ledText,
    rssi: d.rssi,
    snr: d.snr,
    alerts: d.alerts
};
flow.set('api_devices', devices);

let history = flow.get('api_history_' + deviceId) || [];
history.push(devices[deviceId]);
if (history.length > 2000) history = history.slice(-2000);
flow.set('api_history_' + deviceId, history);

let stats = flow.get('api_stats') || { totalMessages: 0, totalAlerts: 0 };
stats.totalMessages++;
if (d.alerts && d.alerts !== 'RAS') stats.totalAlerts++;
flow.set('api_stats', stats);

return msg;

const devices = flow.get('api_devices') || {};
msg.payload = Object.values(devices);
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json'
};
return msg;

const deviceId = msg.req.params.deviceId;
const hours = parseInt(msg.req.query.hours) || 24;
const history = flow.get('api_history_' + deviceId) || [];

const cutoff = Date.now() - (hours * 3600000);
const filtered = history.filter(h => new Date(h.timestamp).getTime() > cutoff);

msg.payload = filtered;
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json'
};
return msg;

const stats = flow.get('api_stats') || { totalMessages: 0, totalAlerts: 0 };
const devices = flow.get('api_devices') || {};

msg.payload = {
    totalMessages: stats.totalMessages,
    totalAlerts: stats.totalAlerts,
    activeDevices: Object.keys(devices).length,
    devices: Object.keys(devices)
};
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json'
};
return msg;
